contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 dummy) public {
        uint256 beforeDifficulty = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 returnedDifficulty = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 afterDifficulty = c.currentDifficulty(); if (__ESBMC_reverted()) return;

        assert(dummy == dummy && returnedDifficulty == beforeDifficulty && afterDifficulty == beforeDifficulty);
    }
}

