// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 dummy) internal {
        uint256 beforeDifficulty;
        try c.currentDifficulty() returns (uint256 __r) { beforeDifficulty = __r; } catch { return; }
        uint256 returnedDifficulty;
        try c.currentDifficulty() returns (uint256 __r) { returnedDifficulty = __r; } catch { return; }
        uint256 afterDifficulty;
        try c.currentDifficulty() returns (uint256 __r) { afterDifficulty = __r; } catch { return; }
        assertTrue(dummy == dummy && returnedDifficulty == beforeDifficulty && afterDifficulty == beforeDifficulty);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
